var s=`0697-akume`;var n=`world-0697`;var t=`TG`;var a=`western-africa`;var r=8;var o=44;var u={en:`Akume`,ua:`Акуме`};var g={en:`Akume is a Togo classic prepared with cornmeal, cassava flour, peanut sauce. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Акуме, страва кухні країни Того зі складниками: кукурудзяна крупа дрібного помелу, борошно маніоку, арахісовий соус. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var l=[{en:`Cook the listed ingredients in simmering water for about 10 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 10 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:10,i:[[`water`,1050,`ml`],[`table-salt`,5,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 24 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 24 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:24,i:[[`cornmeal`,360,`g`],[`cassava-flour`,90,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:7,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`peanut-sauce`,180,`g`]]}];var d={slug:s,id:n,country:`TG`,region:a,servings:8,minutes:44,title:u,text:g,steps:l};export{t as country,d as default,n as id,o as minutes,a as region,r as servings,s as slug,l as steps,g as text,u as title};